DO $patch$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.customer_report(text,text,text,date,date,text,text,text,uuid,integer,integer,timestamptz)'::regprocedure) INTO definition; definition:=replace(definition,'AND inv.invoice_type=''corporate''','AND (EXISTS(SELECT 1 FROM public.bookings corporate_booking WHERE corporate_booking.invoice_id=inv.id AND corporate_booking.corporate_account_id IS NOT NULL) OR EXISTS(SELECT 1 FROM public.coaching_sessions corporate_training WHERE corporate_training.invoice_id=inv.id AND corporate_training.corporate_account_id IS NOT NULL))'); EXECUTE definition; END $patch$;